with x as (select * from json_to_recordset('[{"s":"kairavi","t":"Sonic Juice | Kairavi, RDV & Emski (published 2025)","u":"https://refugeworldwide.com/radio/sonic-juice-rdv-emski-and-kairavi-17-apr-2025"},{"s":"kampai","t":"Demo Mix","u":"https://www.mixcloud.com/Kampai/demo-mix/"},{"s":"kampai","t":"Minimix for opening at Sunburn-Silvassa","u":"https://www.mixcloud.com/Kampai/minimix-for-opening-at-sunburn-silvassa-spinwithola/"},{"s":"kampai","t":"Future Bass Mix 1","u":"https://www.mixcloud.com/Kampai/future-bass-mix-1/"},{"s":"nida","t":"Wild City #257: Nida x Choksi x Rafiki (ParaDisco) (published 2025)","u":"https://soundcloud.com/thewildcity/wild-city-257-nida-x-choksi-x-rafiki"},{"s":"og-shez","t":"Wild City #261: OG SHEZ (published 2026)","u":"https://soundcloud.com/thewildcity/wild-city-261-og-shez"},{"s":"rasa","t":"Mixmag Asia Radio 099: Rasa India (published 2022)","u":"https://www.mixcloud.com/mixmagasia/mixmag-asia-radio-099-rasa-india/"},{"s":"agent","t":"Wild City Mix #143 - AGENT (published 2017)","u":"https://soundcloud.com/thewildcity/wild-city-mix-143-agent"},{"s":"amrisha","t":"Jazz FM Summer Mix // Amrisha (published 2022)","u":"https://soundcloud.com/iamrisha/jazz-fm-iamrisha-170822"},{"s":"amrisha","t":"A Worldwide Thing w/ Mixcloud Co-founder Nikhil Shah // March 2020 (published 2020)","u":"https://soundcloud.com/iamrisha/wwt-mixcloud-march-2020"},{"s":"amrisha","t":"Amrisha @ The Standard (Live Mix Zar Launch Party 21.03.25) (published 2025)","u":"https://www.mixcloud.com/IAMRISHA/amrisha-the-standard-live-mix-zar-launch-party-210325/"},{"s":"amrisha","t":"Musica Macondo // Brilliant Corners // Amrisha (live)","u":"https://www.mixcloud.com/IAMRISHA/musica-macondo-brilliant-corners-amrisha-live-mix/"},{"s":"bindas","t":"NDCR #067: BINDAS (published 2026)","u":"https://soundcloud.com/new-delhi-community-radio/ndcr-mix-final-bindas"}]'::json) as x(s text,t text,u text) where exists (select 1 from public.artists a where a.slug=x.s)), ins as (insert into public.artist_tracklists (artist_slug,mix_title,url,tracks) select x.s,x.t,x.u,'[]'::jsonb from x on conflict (artist_slug,url) do nothing returning 1), fill as (update public.artists a set mix_url=f.u from (select distinct on (x.s) x.s,x.u from x order by x.s, (x.u ~ '(soundcloud\.com|youtube\.com|youtu\.be|mixcloud\.com)') desc) f where a.slug=f.s and a.mix_url is null returning 1) select (select count(*) from ins) ins, (select count(*) from fill) filled;